// Builds the page: dist/rikuy.html (the editor with its fonts and styles, one file), dist/index.html
// (the same page as a whole document), dist/git.js, dist/LICENSES.txt, and the worker's own
// scripts in dist/tex (the TeX tree's packs and wasm come from tex/build_tree.py). Unless
// RIKUY_SHARE is set, index.html is the installed app, with its service worker, manifest, icons
// and libraries beside it (build/app.mjs).
// Usage: node build.mjs [--dev]   (npm run build; --dev leaves the bundle unminified, for debugging)
//   env: RIKUY_OUT     where the page goes (default dist/)
//        RIKUY_MIRROR  a full TeX Live mirror the page may read (build_tree.py mirror), e.g. "mirror/":
//                       for a self-hosted Rikuy; a page on claude.ai can reach only its own files
//        RIKUY_SHARE   the address share links open (default: the page's own, which a page in a frame lacks);
//                       set for the copy inside the claude.ai artifact, whose host refuses service
//                       workers and installation, so it also builds no installed app
//        RIKUY_NO_WORD leave pandoc (Word import and export, 16 MB) out: the claude.ai copy, which has
//                      no room for it; its Word buttons say where Word support is
//        RIKUY_WORD_HOST the address of a copy with Word support, named in that message
import fs from 'fs';
import path from 'path';
import zlib from 'zlib';
import crypto from 'crypto';
import { build } from 'esbuild';
import { appPage, appFiles, finishApp, cleanApp } from './build/app.mjs';

const root = path.dirname(new URL(import.meta.url).pathname);
const R = (p) => path.join(root, p);
// where the built page goes (RIKUY_OUT lets tests build next to a separate set of packs)
const OUT = process.env.RIKUY_OUT || R('dist');
const O = (p) => path.join(OUT, p);
const b64 = (p) => fs.readFileSync(p).toString('base64');
// the installed app (service worker, manifest, offline copy): every build but the artifact's
const APP = !process.env.RIKUY_SHARE;
// (the artifact's copy, built with RIKUY_SHARE, has no room for it either way)
const WORD = !process.env.RIKUY_NO_WORD && !process.env.RIKUY_SHARE;

// 1. sample
const sample = { 'main.tex': fs.readFileSync(R('sample/main.tex'), 'utf8'), 'refs.bib': fs.readFileSync(R('sample/refs.bib'), 'utf8') };
fs.writeFileSync(R('src/sample.js'), '// Generated by build.mjs from sample/main.tex and sample/refs.bib: edit those, not this file.\n'
  + 'export const SAMPLE = ' + JSON.stringify(sample, null, 0) + ';\n');

// 2. bundle
// RIKUY_MIRROR: where a self-hosted build keeps the full TeX Live mirror (e.g. "mirror/")
// RIKUY_SHARE: the address share links open, for a copy that cannot see its own (one inside a frame)
const out = await build({ entryPoints: [R('src/app.js')], bundle: true, format: 'iife', minify: process.argv.includes('--dev') ? false : true, write: false, target: ['chrome100', 'firefox100', 'safari15'], legalComments: 'none', charset: 'utf8', define: { __RIKUY_MIRROR__: JSON.stringify(process.env.RIKUY_MIRROR || ''), __RIKUY_SHARE__: JSON.stringify(process.env.RIKUY_SHARE || ''), __RIKUY_APP__: JSON.stringify(APP), __RIKUY_WORD__: JSON.stringify(WORD), __RIKUY_WORD_HOST__: JSON.stringify(process.env.RIKUY_WORD_HOST || '') } });
let js = out.outputFiles[0].text.replace(/<\/script/gi, '<\\/script');

// 2b. git, loaded by the page the first time the Git panel opens; the packages it bundles keep
// their license notices in LICENSES.txt (step 8), which the banner names
const gitOut = await build({ entryPoints: [R('src/git.js')], bundle: true, format: 'esm', minify: true, write: false, metafile: true, target: ['chrome100', 'firefox100', 'safari15'], legalComments: 'none', charset: 'utf8', define: { global: 'globalThis' }, banner: { js: '/* Rikuy\'s Git panel, with isomorphic-git and the npm packages it needs; their licenses are in LICENSES.txt beside the page. */' } });
const gitJs = gitOut.outputFiles[0].text;

// 3. fonts
const F = (family, file, weight, style) => `@font-face{font-family:"${family}";src:url(data:font/woff2;base64,${b64(R('build/fonts/' + file))}) format("woff2");font-weight:${weight};font-style:${style};font-display:block}`;
const fonts = [
  F('Paper Modern Serif', 'cmu-serif-500-roman.woff2', 400, 'normal'),
  F('Paper Modern Serif', 'cmu-serif-500-italic.woff2', 400, 'italic'),
  F('Paper Modern Serif', 'cmu-serif-700-roman.woff2', 700, 'normal'),
  F('Paper Modern Serif', 'cmu-serif-700-italic.woff2', 700, 'italic'),
  F('Paper Modern Typewriter', 'cmu-typewriter-text-500-roman.woff2', 400, 'normal'),
  F('Paper Modern Sans', 'cmu-sans-serif-500-roman.woff2', 400, 'normal'),
  F('Paper Modern Sans', 'cmu-sans-serif-700-roman.woff2', 700, 'normal')
].join('\n');
// The interface's fonts, IBM Plex Sans and Mono, inside the page as the text fonts are: fetched
// from a font server while the page runs, they told it the address of everyone who opened it, and
// the artifact host lets a page take fonts only as data: (font-src data: and Google's server).
// They are Google Fonts' own Latin cut (Latin-1, general punctuation and a few symbols: every
// character of the interface's text) and its Latin Extended cut (Ł, ő, ş, ā, ...: a file name, a
// project or an author's name in the interface), as @fontsource ships them, unchanged;
// package-lock.json pins them. Each face takes its unicode-range from the package's style sheet,
// so the browser uses the extended cut only for text that needs it, and characters past both fall
// back to the next font, as they did when Google served the same cuts.
// The Latin Extended faces add 101 KB to the page as data: (75 KB of fonts), under the 200 KB the
// artifact can spare, so rikuy.html carries them; the hosted page (index.html) takes them as files
// in fonts/ instead, named by their hash and cached for good, fetched only when a character needs
// them (fontFiles, below).
const plexFace = (pkg, weight, cut) => {
  const file = `${pkg}-${cut}-${weight}-normal.woff2`;
  const dir = R('node_modules/@fontsource/' + pkg);
  const face = fs.readFileSync(path.join(dir, weight + '.css'), 'utf8').split('@font-face').find((b) => b.includes('/files/' + file + ')'));
  const family = face && (face.match(/font-family:\s*'([^']+)'/) || [])[1];
  const range = face && (face.match(/unicode-range:\s*([^;]+);/) || [])[1];
  if (!family || !range) throw new Error('@fontsource/' + pkg + ': no ' + cut + ' face for weight ' + weight + ' in ' + weight + '.css');
  const bytes = fs.readFileSync(path.join(dir, 'files', file));
  const css = (src) => `@font-face{font-family:"${family}";src:url(${src}) format("woff2");font-weight:${weight};font-style:normal;font-display:${cut === 'latin' ? 'block' : 'swap'};unicode-range:${range}}`;
  // the hosted page's file: its name carries the first 16 hex digits of its SHA-256 (build/app.mjs)
  const name = 'fonts/' + file.replace(/\.woff2$/, '') + '-' + crypto.createHash('sha256').update(bytes).digest('hex').slice(0, 16) + '.woff2';
  return { inline: css('data:font/woff2;base64,' + bytes.toString('base64')), asFile: css(name), name, bytes };
};
const PLEX = [['ibm-plex-sans', 400], ['ibm-plex-sans', 500], ['ibm-plex-sans', 600], ['ibm-plex-mono', 400], ['ibm-plex-mono', 500]];
const uiFonts = PLEX.map(([p, w]) => plexFace(p, w, 'latin').inline).join('\n');
const extFaces = PLEX.map(([p, w]) => plexFace(p, w, 'latin-ext'));
const extInline = extFaces.map((f) => f.inline).join('\n');

// 4. KaTeX css with embedded woff2
let katexCss = fs.readFileSync(R('node_modules/katex/dist/katex.min.css'), 'utf8');
katexCss = katexCss.replace(/src:url\(fonts\/([A-Za-z0-9_-]+)\.woff2\) format\("woff2"\)(,url\([^)]*\) format\("[^"]*"\))*/g, (m, name) => `src:url(data:font/woff2;base64,${b64(R('node_modules/katex/dist/fonts/' + name + '.woff2'))}) format("woff2")`);
if (/url\(fonts\//.test(katexCss)) throw new Error('KaTeX font url left behind');

// 5. CodeMirror css
const cmCss = fs.readFileSync(R('node_modules/codemirror/lib/codemirror.css'), 'utf8');

// 6. assemble
const css = fs.readFileSync(R('src/app.css'), 'utf8');
let html = fs.readFileSync(R('src/template.html'), 'utf8');
// the installed app's marks in the status bar (src/pwa.js shows them); the artifact has none
const appStatus = APP ? '<span id="st-net" hidden title="No network. Typing works and is kept in this browser; compiling uses the TeX files this browser has kept.">Offline</span>'
  + '<button id="st-update" class="linkish" type="button" hidden>Update ready</button>'
  + '<button id="b-offline" class="linkish" type="button" hidden title="Keep the TeX engine and the packages a typical paper needs in this browser, so compiling works without a network">Make available offline</button>' : '';
html = html.replace('/*FONTS*/', () => fonts + '\n' + uiFonts + '\n' + extInline).replace('/*KATEX*/', () => katexCss).replace('/*CODEMIRROR*/', () => cmCss).replace('/*APP*/', () => css).replace('/*APPJS*/', () => js).replace('<!--APPSTATUS-->', () => appStatus);
html += '\n<!-- Rikuy is free software under the GNU AGPL 3.0 or later: https://github.com/pdfrackebrandt/rikuy (SOURCES.md says where the source of every part is). Licenses of what it ships: LICENSES.txt beside this page. -->\n';
fs.mkdirSync(OUT, { recursive: true });
fs.writeFileSync(O('rikuy.html'), html);
// rikuy.html is the body the artifact host wraps in a document (test/serve.py does the same);
// index.html is that document, so any static web server can serve dist/ as it is. Without the
// doctype and charset a browser reads the page in quirks mode and as Latin-1, and the script fails.
const SKELETON = '<!doctype html><html><head><meta charset=utf8><meta name=viewport content="width=device-width,initial-scale=1,viewport-fit=cover">'
  + '<style>:root{color-scheme:light;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}'
  + 'body{margin:0;font:14px system-ui,sans-serif;background:#fafafa}img{max-width:100%}[hidden]{display:none!important}</style></head><body>';
// the hosted build's index.html is the installed app: its head names the version, the manifest and
// the icons, and it takes KaTeX from lib/ (build/app.mjs); finishApp stamps the version at the end
// it also takes the Latin Extended faces from fonts/ rather than inside the page
if (APP) {
  fs.rmSync(O('fonts'), { recursive: true, force: true });
  fs.mkdirSync(O('fonts'), { recursive: true });
  for (const f of extFaces) fs.writeFileSync(O(f.name), f.bytes);
}
fs.writeFileSync(O('index.html'), APP ? appPage(OUT, html.replace(extInline, () => extFaces.map((f) => f.asFile).join('\n')), SKELETON) : SKELETON + html + '</body></html>');
fs.writeFileSync(O('git.js'), gitJs);
console.log(O('rikuy.html'), (html.length / 1024).toFixed(0) + ' KB', 'js', (js.length / 1024).toFixed(0) + ' KB');

// 7. the TeX engine's own files (the packs and wasm chunks come from tex/build_tree.py)
fs.mkdirSync(O('tex'), { recursive: true });
fs.copyFileSync(R('tex/engine.js'), O('tex/engine.js'));
fs.copyFileSync(R('tex/vendor/busytex.js'), O('tex/busytex.js'));
fs.copyFileSync(R('node_modules/fflate/umd/index.js'), O('tex/fflate.js'));
fs.copyFileSync(R('tex/vendor/biber.js'), O('tex/biber.js'));
fs.copyFileSync(R('tex/shell.js'), O('tex/shell.js'));
fs.copyFileSync(R('tex/tools.js'), O('tex/tools.js'));
const escapeCtl = (t) => t.replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g, (c) => '\\x' + c.charCodeAt(0).toString(16).padStart(2, '0'));
// the programs TeX's shell escape runs ship as ES modules; the worker is a classic script, so
// each becomes a script that leaves its factory on self (its wasm comes from build_tree.py)
const classic = (src, name) => {
  let t = fs.readFileSync(R(src), 'utf8');
  const n = (t.match(/import\.meta\.url/g) || []).length;
  t = t.replace(/import\.meta\.url/g, 'self.__galleyToolBase').replace(/export default Module;?/, 'self.' + name + ' = Module;');
  if (!n || !t.includes('self.' + name)) throw new Error('unexpected module shape: ' + src);
  return escapeCtl(t);
};
const gsJs = classic('node_modules/@okathira/ghostpdl-wasm/dist/gs.js', 'GalleyGs');
// tools.js resets Ghostscript's stack pointer through the exports this glue calls stackSave (Y,
// export "ba") and stackRestore (X, export "$"), as its invoke wrappers use them
if (!gsJs.includes('X=c.$;') || !gsJs.includes('Y=c.ba;') || !/var c=Y\(\);try\{T\.get\(a\)\(b\)\}catch\(d\)\{X\(c\);/.test(gsJs)) throw new Error('ghostpdl-wasm glue changed: check the stack exports in tools.js makeGs');
fs.writeFileSync(O('tex/gs.js'), gsJs);
// programs built for Rikuy (tex/build_tools.sh) are classic scripts already
for (const t of ['dvips', 'asy', 'xindy', 'gnuplot']) fs.writeFileSync(O('tex/' + t + '.js'), escapeCtl(fs.readFileSync(R('tex/vendor/' + t + '/' + t + '.js'), 'utf8')));
// Pyodide's loader is a classic script already; its runtime comes from build_tree.py
fs.writeFileSync(O('tex/pyodide.js'), escapeCtl(fs.readFileSync(R('node_modules/pyodide/pyodide.js'), 'utf8')).replace(/\n\/\/# sourceMappingURL=.*$/, '\n'));
// the artifact host refuses raw control bytes in text files; they only occur inside string
// literals here, where \xHH means the same. pdf.js itself ships beside its worker, so the page
// imports it from its own site (src/pdfview.js), never from a CDN
for (const f of ['pdf.min.mjs', 'pdf.worker.min.mjs']) fs.writeFileSync(O('tex/' + f), escapeCtl(fs.readFileSync(R('node_modules/pdfjs-dist/build/' + f), 'utf8')));
// tex/tex-smoke.html, the worker's test page, is not part of the page: it passes any ?texlive= to
// the worker, where the editor takes a mirror only from its own site. test/serve.py serves it
// from tex/ for the tests and build scripts; a dist/ built before keeps no copy of it.
fs.rmSync(O('tex-smoke.html'), { force: true });
console.log(O('tex'), fs.readdirSync(O('tex')).length, 'files');

// 7b. Word: pandoc (npm's pandoc-wasm, the pandoc project's own WebAssembly build) and the worker
// that runs it, in dist/word/. The host refuses files over 25 MiB, so pandoc.wasm goes gzipped
// (59 MB to 16 MB) in numbered parts of at most PART bytes; pandoc.json names each part with its
// size and SHA-256, and the SHA-256 of the gzip and of pandoc.wasm itself, which the worker checks
// before it runs anything (src/wordworker.js). The parts' names carry the hash, so a new pandoc is
// never mixed with an old one in a cache. Without Word (RIKUY_NO_WORD) none of it is written.
let wordInfo = null;
if (WORD) {
  const W = (p) => path.join(O('word'), p);
  fs.mkdirSync(O('word'), { recursive: true });
  const wbuild = await build({ entryPoints: [R('src/wordworker.js')], bundle: true, format: 'iife', minify: !process.argv.includes('--dev'), write: false, target: ['chrome100', 'firefox100', 'safari15'], legalComments: 'none', charset: 'utf8', banner: { js: '/* Rikuy\'s Word worker, with fflate and @bjorn3/browser_wasi_shim; pandoc runs in it. Licenses: LICENSES.txt beside the page. */' } });
  fs.writeFileSync(W('word.js'), escapeCtl(wbuild.outputFiles[0].text));
  const wasm = fs.readFileSync(R('node_modules/pandoc-wasm/src/pandoc.wasm'));
  const sha = (b) => crypto.createHash('sha256').update(b).digest('hex');
  const whole = sha(wasm);
  const PART = 12 * 1024 * 1024;
  const meta = JSON.parse(fs.readFileSync(R('node_modules/pandoc-wasm/package.json'), 'utf8'));
  const version = fs.readFileSync(R('node_modules/pandoc-wasm/pandoc-version.txt'), 'utf8').trim();
  let man = null;
  // the gzip takes a few seconds: a manifest of the same pandoc with all its parts intact is kept
  try {
    const old = JSON.parse(fs.readFileSync(W('pandoc.json'), 'utf8'));
    if (old.sha256 === whole && old.parts.every((p) => fs.existsSync(W(p.name)) && sha(fs.readFileSync(W(p.name))) === p.sha256)) man = old;
  } catch (e) { man = null; }
  if (!man) {
    for (const f of fs.readdirSync(O('word'))) if (/^pandoc-.*\.bin$/.test(f)) fs.rmSync(W(f));
    const gz = zlib.gzipSync(wasm, { level: 9 });
    const parts = [];
    for (let i = 0, k = 0; i < gz.length; i += PART, k++) {
      const b = gz.subarray(i, i + PART);
      const name = 'pandoc-' + whole.slice(0, 12) + '-' + k + '.bin';
      fs.writeFileSync(W(name), b);
      parts.push({ name, size: b.length, sha256: sha(b) });
    }
    man = { v: 1, pandoc: version, package: meta.name + ' ' + meta.version, license: meta.license, size: wasm.length, sha256: whole, gz: { size: gz.length, sha256: sha(gz) }, parts };
    fs.writeFileSync(W('pandoc.json'), JSON.stringify(man, null, 1) + '\n');
  }
  if (man.parts.some((p) => p.size > 24 * 1024 * 1024)) throw new Error('a part of pandoc.wasm is over 24 MiB');
  wordInfo = man;
  console.log(O('word'), 'pandoc ' + man.pandoc + ',', man.parts.length, 'parts,', (man.gz.size / 1e6).toFixed(1) + ' MB gzipped (' + (man.size / 1e6).toFixed(1) + ' MB)');
} else fs.rmSync(O('word'), { recursive: true, force: true });

// 8. LICENSES.txt: NOTICE, then the license texts of what dist/ holds and the notices of the
// libraries inside its programs. The MIT, BSD and Apache licenses ask that their notices travel
// with every copy, and the minified bundles and compiled programs drop them.
// The npm packages: those git.js bundles, and those whose files the steps above copy.
const pkgOf = (f) => (f.match(/node_modules\/((?:@[^/]+\/)?[^/]+)\//) || [])[1];
const npm = new Set(Object.keys(gitOut.metafile.inputs).map(pkgOf).filter(Boolean));
for (const p of ['katex', 'codemirror', 'fflate', 'pdfjs-dist', 'pyodide', '@fontsource/ibm-plex-sans', '@fontsource/ibm-plex-mono']) npm.add(p);
// the installed app ships the libraries the artifact takes from jsDelivr (lib/)
if (APP) for (const p of ['jszip', 'mathlive']) npm.add(p);
// the Word worker: pandoc-wasm's JavaScript (MIT; pandoc itself is GPL-2.0-or-later, below) and the WASI shim
if (WORD) for (const p of ['pandoc-wasm', '@bjorn3/browser_wasi_shim']) npm.add(p);
const byText = new Map();  // packages whose license file says the same, printed once
for (const p of [...npm].sort()) {
  const dir = R('node_modules/' + p);
  const meta = JSON.parse(fs.readFileSync(path.join(dir, 'package.json'), 'utf8'));
  const file = fs.readdirSync(dir).sort().find((n) => /^(licen[cs]e|copying)/i.test(n));
  const text = file ? fs.readFileSync(path.join(dir, file), 'utf8').trim() : '(The package has no license file; its package.json says ' + (meta.license || 'nothing') + ', whose text is above or at spdx.org.)';
  if (!byText.has(text)) byText.set(text, []);
  byText.get(text).push(p + ' ' + meta.version + ' (' + (meta.license || '?') + ')');
}
const rule = (title) => '\n\n' + '='.repeat(100) + '\n' + title + '\n' + '='.repeat(100) + '\n\n';
let lic = 'Rikuy and what it ships. The source of Rikuy and the address of the exact source of every\n'
  + 'part: https://github.com/pdfrackebrandt/rikuy (SOURCES.md).\n\n' + fs.readFileSync(R('NOTICE'), 'utf8').trim();
lic += rule('GNU Affero General Public License 3.0: Rikuy, BusyTeX, Ghostscript') + fs.readFileSync(R('LICENSE'), 'utf8').trim();
const texts = [['GPL-3.0', 'Asymptote as built (with GSL), GSL, Xpdf'], ['GPL-2.0', 'TeX Live\'s programs, dvips, xindy, FFTW, GMP, Xpdf, libpaper' + (WORD ? ', pandoc (word/)' : '')], ['LGPL-3.0', 'GMP, Asymptote, its PRC library'],
  ['LGPL-2.1', 'kpathsea, ECL, Graphite2, TECkit, btparse'], ['MPL-2.0', 'Pyodide, Eigen'], ['Apache-2.0', 'pdf.js and npm packages below'], ['Artistic-2.0', 'biber'], ['gnuplot', 'gnuplot']];
for (const [id, who] of texts) lic += rule((id === 'gnuplot' ? 'The gnuplot license' : id) + ': ' + who) + fs.readFileSync(R('LICENSES/' + id + '.txt'), 'utf8').trim();
lic += rule('SIL Open Font License 1.1: Paper Modern, the page\'s text fonts (KaTeX\'s fonts carry the same license in their own name tables; IBM Plex Sans and Mono, the interface\'s fonts, have it with IBM\'s copyright under npm below)') + fs.readFileSync(R('build/fonts/OFL.txt'), 'utf8').trim();
// the notices of the libraries compiled into the programs (MIT, BSD and the like ask for them
// with binary copies too), one file per program; each file's first line is its title
for (const f of fs.readdirSync(R('LICENSES/third-party')).filter((n) => n.endsWith('.txt') && (WORD || n !== 'pandoc.txt')).sort()) {
  const [title, ...rest] = fs.readFileSync(R('LICENSES/third-party/' + f), 'utf8').trim().split('\n');
  lic += rule(title + ' (LICENSES/third-party/' + f + ')') + rest.join('\n').trim();
}
for (const [text, pkgs] of byText) lic += rule('npm: ' + pkgs.join(', ')) + text;
fs.writeFileSync(O('LICENSES.txt'), lic + '\n');
console.log(O('LICENSES.txt'), npm.size, 'npm packages', (lic.length / 1024).toFixed(0) + ' KB');

// 9. the installed app: lib/, icons/, the manifest, then the version over everything above,
// stamped into index.html and sw.js (build/app.mjs). An artifact build leaves none of it behind.
if (APP) {
  appFiles(OUT);
  const r = finishApp(OUT);
  console.log(O('sw.js'), 'version', r.v + ',', r.files, 'files,', (r.precache / 1048576).toFixed(1), 'MB kept at install');
} else cleanApp(OUT);
